16:         return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())
17:       }, Boolean(selector))
18:       if (eligible) matches.push(control)
19:     }
20:     if (matches.length > 1) return { clicked: false, reason: 'ambiguous' }
21:     if (matches.length === 1) {
22:       try { await matches[0].click({ trial: true, timeout: 2000 }) }
23:       catch (error) {
24:         if (error.name === 'TimeoutError') return { clicked: false, reason: 'not-actionable' }
25:         throw error
26:       }
27:       await matches[0].click({ timeout: 2000, noWaitAfter: true })
28:       return { clicked: true }
29:     }
30:     if (Date.now() >= deadline) break
31:     await page.waitForTimeout(Math.min(200, Math.max(0, deadline - Date.now())))
32:   } while (Date.now() <= deadline)
33:   return { clicked: false, reason: 'not-found' }
34: }

input.content:
:root {
  --bg: #0b1510;
  --bg-deep: #07100c;
  --panel: #11211a;
  --panel-2: #162a20;
  --panel-3: #1b3226;
  --line: rgba(231, 211, 170, .13);
  --line-bright: rgba(231, 211, 170, .28);
  --parchment: #f2e8d2;
  --muted: #9ba99d;
  --muted-2: #728476;
  --gold: #e6b75e;
  --gold-bright: #ffdb91;
  --gold-dim: #9b7638;
  --player: #51c3a0;
  --player-deep: #1c725b;
  --player-glow: rgba(81, 195, 160, .28);
  --rival: #d76f51;
  --rival-deep: #8e3d2f;
  --rival-glow: rgba(215, 111, 81, .25);
  --science: #76b7d8;
  --danger: #e6795f;
  --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  --sans: "Avenir Next", Avenir, "Segoe UI", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --shadow-lg: 0 26px 80px rgba(0, 0, 0, .45);
  --radius: 14px;
}

* { box-sizing: border-box; }
html, body { margin: 0; min-height: 100%; }
body {
  background: var(--bg-deep);
  color: var(--parchment);
  font-family: var(--sans);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow: hidden;
}
button { font: inherit; color: inherit; }
button:focus-visible, [tabindex]:focus-visible { outline: 2px solid var(--gold-bright); outline-offset: 2px; }
svg { display: block; }
[hidden] { display: none !important; }

.ambient {
  position: fixed;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(80% 70% at 50% 10%, rgba(52, 97, 67, .24), transparent 60%),
    radial-gradient(60% 60% at 90% 90%, rgba(112, 71, 34, .16), transparent 60%),
    radial-gradient(40% 60% at 0% 80%, rgba(25, 86, 75, .16), transparent 60%),
    linear-gradient(145deg, #0d1a14 0%, #08110d 55%, #0b1712 100%);
}
.ambient::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: .15;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.35'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}
.svg-sprite { position: absolute; width: 0; height: 0; overflow: hidden; }

.app {
  height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ---------- top bar ---------- */
.topbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 22px;
  min-height: 82px;
  padding: 14px 22px 12px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(9, 18, 13, .88), rgba(9, 18, 13, .38));
  backdrop-filter: blur(12px);
  position: relative;
  z-index: 30;
}
.topbar::after {
  content: "";
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(230, 183, 94, .28), transparent);
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 230px; }
.brand-crest {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--gold-bright);
  background: radial-gradient(circle at 35% 30%, #25392b, #101d16 60%);
  border: 1px solid rgba(230, 183, 94, .55);
  box-shadow: 0 0 0 4px rgba(230, 183, 94, .06), inset 0 0 20px rgba(230, 183, 94, .1);
}
.brand-crest svg { width: 25px; height: 25px; }
.brand-copy h1 {
  margin: 0;
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: .4px;
  color: #f4ead5;
}
.brand-copy p {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 2.2px;
  text-transform: uppercase;
}
.resource-rail {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 auto;
}
.res-chip {
  height: 48px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 12px 0 8px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(28, 48, 37, .7), rgba(17, 32, 24, .7));
  box-shadow: inset 0 1px rgba(255, 255, 255, .035);
  transition: border-color .2s, transform .2s;
}
.res-chip:hover { border-color: var(--line-bright); }
.res-chip.pulse { animation: chip-pulse .45s ease; }
.res-icon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
}
.res-icon svg { width: 17px; height: 17px; }
.res-icon.gold { color: var(--gold); background: rgba(230, 183, 94, .1); }
.res-icon.science { color: var(--science); background: rgba(118, 183, 216, .1); }
.res-icon.legacy { color: #e9d7a8; background: rgba(233, 215, 168, .08); }
.res-copy { display: flex; flex-direction: column; line-height: 1; }
.res-copy small {
  font-size: 8px;
  letter-spacing: 1.6px;
  color: var(--muted-2);
  text-transform: uppercase;
}
.res-copy strong {
  margin-top: 4px;
  font-family: var(--serif);
  font-size: 18px;
  font-weight: 600;
  color: #f6ecd6;
  font-variant-numeric: tabular-nums;
}
.res-rate {
  align-self: flex-end;
  margin-bottom: 8px;
  font-size: 9px;
  color: var(--player);
  font-weight: 700;
  letter-spacing: .3px;
}
.legacy-chip { min-width: 94px; }
.turn-meter {
  min-width: 110px;
  height: 48px;
  padding: 8px 11px;
  border: 1px solid rgba(230, 183, 94, .2);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(230, 183, 94, .1), rgba(230, 183, 94, .03));
}
.turn-copy { display: flex; align-items: baseline; gap: 5px; line-height: 1; }
.turn-copy span { font-size: 8px; letter-spacing: 1.7px; color: var(--gold); text-transform: uppercase; }
.turn-copy strong { font-family: var(--serif); font-size: 20px; font-weight: 600; color: #f8efd9; font-variant-numeric: tabular-nums; }
.turn-copy em { font-style: normal; font-size: 10px; color: var(--muted); }
.turn-track {
  margin-top: 6px;
  height: 3px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(0, 0, 0, .35);
}
.turn-track i {
  display: block;
  height: 100%;
  width: 5%;
  border-radius: inherit;
  background: linear-gradient(90deg, #a9803c, var(--gold-bright));
  box-shadow: 0 0 10px rgba(230, 183, 94, .5);
  transition: width .4s ease;
}
.top-actions { display: flex; align-items: center; gap: 8px; }
.icon-btn {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(22, 42, 32, .72);
  color: var(--muted);
  cursor: pointer;
  transition: .18s ease;
}
.icon-btn svg { width: 18px; height: 18px; }
.icon-btn:hover { color: var(--parchment); border-color: var(--line-bright); transform: translateY(-1px); }
.btn-end {
  height: 44px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 17px 0 19px;
  border: 1px solid rgba(255, 223, 159, .6);
  border-radius: 9px;
  background: linear-gradient(180deg, #f0c66f, #c89542);
  color: #2a1b07;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 4px 16px rgba(230, 183, 94, .2), inset 0 1px rgba(255, 255, 255, .5);
  transition: .18s ease;
}
.btn-end svg { width: 15px; height: 15px; transition: transform .18s; }
.btn-end:hover:not(:disabled) { transform: translateY(-1px); filter: brightness(1.06); box-shadow: 0 7px 22px rgba(230, 183, 94, .3), inset 0 1px rgba(255, 255, 255, .5); }
.btn-end:hover:not(:disabled) svg { transform: translateX(2px); }
.btn-end:active:not(:disabled) { transform: translateY(0); }
.btn-end:disabled { opacity: .5; cursor: wait; }
.btn-end.finish { background: linear-gradient(180deg, #f1d58e, #d9a94e); }

/* ---------- layout ---------- */
.layout {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: 276px minmax(420px, 1fr) 322px;
  gap: 16px;
  padding: 16px 20px 18px;
}
.panel {
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(230, 183, 94, .18) transparent;
}
.panel::-webkit-scrollbar { width: 5px; }
.panel::-webkit-scrollbar-thumb { background: rgba(230, 183, 94, .18); border-radius: 99px; }
.left-panel { display: flex; flex-direction: column; gap: 11px; padding-right: 2px; }
.right-panel { padding-right: 2px; }

.card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(145deg, rgba(27, 48, 37, .72), rgba(14, 27, 21, .82)),
    repeating-linear-gradient(90deg, transparent 0 32px, rgba(255, 255, 255, .01) 32px 33px);
  box-shadow: inset 0 1px rgba(255, 255, 255, .035), 0 12px 30px rgba(0, 0, 0, .12);
  padding: 14px;
  position: relative;
}
.card::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid rgba(231, 211, 170, .045);
  border-radius: calc(var(--radius) - 6px);
  pointer-events: none;
}
.card-eyebrow {
  font-size: 8px;
  letter-spacing: 2.2px;
  text-transform: uppercase;
  color: var(--gold);
}
.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--line);
  font-family: var(--serif);
  font-size: 14px;
  letter-spacing: .7px;
}
.card-head small { font-family: var(--sans); font-size: 9px; letter-spacing: .6px; color: var(--muted-2); }
.legacy-card { padding: 15px 16px 13px; overflow: hidden; }
.legacy-card::after {
  content: "";
  position: absolute;
  right: -35px;
  top: -55px;
  width: 150px;
  height: 150px;
  border: 1px solid rgba(230, 183, 94, .08);
  border-radius: 50%;
  box-shadow: 0 0 0 18px rgba(230, 183, 94, .025), 0 0 0 36px rgba(230, 183, 94, .015);
}
.legacy-score-row { display: flex; align-items: flex-end; gap: 10px; margin: 6px 0 13px; }
.legacy-big {
  font-family: var(--serif);
  font-size: 44px;
  line-height: .9;
  font-weight: 500;
  color: #f7eed9;
  letter-spacing: -1px;
  font-variant-numeric: tabular-nums;
}
.legacy-delta {
  margin-bottom: 4px;
  padding: 3px 7px;
  border-radius: 999px;
  border: 1px solid rgba(81, 195, 160, .22);
  color: var(--player);
  background: rgba(81, 195, 160, .07);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .6px;
  text-transform: uppercase;
}
.legacy-delta.behind { color: var(--rival); border-color: rgba(215, 111, 81, .25); background: rgba(215, 111, 81, .08); }
.legacy-race { display: flex; flex-direction: column; gap: 4px; }
.race-row { display: flex; justify-content: space-between; margin-top: 2px; font-size: 9px; color: var(--muted); }
.race-row b { font-weight: 600; color: #e9dfc9; font-variant-numeric: tabular-nums; }
.race-row.player span::before,
.race-row.rival span::before {
  content: "";
  display: inline-block;
  width: 5px; height: 5px;
  margin-right: 5px;
  border-radius: 50%;
  background: var(--player);
  box-shadow: 0 0 6px var(--player-glow);
  vertical-align: 1px;
}
.race-row.rival span::before { background: var(--rival); box-shadow: 0 0 6px var(--rival-glow); }
.race-track { height: 4px; overflow: hidden; border-radius: 99px; background: rgba(255, 255, 255, .055); }
.race-track i { display: block; height: 100%; width: 34%; border-radius: inherit; background: linear-gradient(90deg, var(--player-deep), var(--player)); transition: width .5s ease; }
.rival-track i { background: linear-gradient(90deg, var(--rival-deep), var(--rival)); }
.realm-card { padding-bottom: 8px; }
.city-list { display: flex; flex-direction: column; }
.city-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 3px;
  border-bottom: 1px solid rgba(231, 211, 170, .07);
  cursor: pointer;
  transition: .15s;
}
.city-row:last-child { border-bottom: 0; }
.city-row:hover { background: rgba(255, 255, 255, .028); }
.city-row.selected { background: rgba(230, 183, 94, .055); }
.city-sigil {
  width: 28px; height: 28px;
  flex: 0 0 auto;
  display: grid; place-items: center;
  border-radius: 7px;
  color: #e6d8b7;
  border: 1px solid rgba(255, 255, 255, .09);
}
.city-sigil svg { width: 24px; height: 18px; }
.city-sigil.player { background: linear-gradient(145deg, rgba(81, 195, 160, .30), rgba(21, 76, 60, .4)); border-color: rgba(81, 195, 160, .35); color: #9be4ce; }
.city-sigil.rival { background: linear-gradient(145deg, rgba(215, 111, 81, .3), rgba(92, 39, 31, .4)); border-color: rgba(215, 111, 81, .3); color: #f0a58d; }
.city-copy { flex: 1; min-width: 0; }
.city-copy strong { display: block; font-family: var(--serif); font-size: 13px; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.city-copy small { display: block; margin-top: 2px; font-size: 8px; color: var(--muted-2); letter-spacing: .5px; text-transform: uppercase; }
.city-pop { font-size: 9px; color: var(--muted); padding: 2px 6px; border-radius: 999px; background: rgba(0, 0, 0, .2); }
.research-card { padding-bottom: 11px; }
.text-btn {
  border: 0; background: none; padding: 2px;
  color: var(--gold); font-size: 9px; letter-spacing: .4px; cursor: pointer;
}
.text-btn:hover { color: var(--gold-bright); text-decoration: underline; }
.research-current { display: flex; align-items: center; gap: 9px; padding: 11px 0 8px; }
.research-icon { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; background: rgba(118, 183, 216, .09); color: var(--science); border: 1px solid rgba(118, 183, 216, .16); }
.research-icon svg { width: 17px; height: 17px; }
.research-copy { flex: 1; min-width: 0; }
.research-copy strong { display: block; font-family: var(--serif); font-size: 13px; font-weight: 500; }
.research-copy small { display: block; margin-top: 2px; font-size: 8px; color: var(--muted-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.progress-track { height: 5px; border-radius: 99px; overflow: hidden; background: rgba(0, 0, 0, .35); box-shadow: inset 0 1px 2px rgba(0, 0, 0, .3); }
.progress-track i { display: block; height: 100%; width: 0%; border-radius: inherit; background: linear-gradient(90deg, #2f7b91, #74c5df); box-shadow: 0 0 8px rgba(118, 183, 216, .35); transition: width .45s ease; }
.research-meta { display: flex; justify-content: space-between; margin-top: 6px; color: var(--muted-2); font-size: 8px; letter-spacing: .3px; }
.research-next {
  width: 100%; margin-top: 8px; border: 1px solid rgba(118, 183, 216, .25); border-radius: 7px;
  padding: 6px; color: var(--science); background: rgba(118, 183, 216, .07); font-size: 9px; cursor: pointer;
}
.chronicle-card { flex: 1; min-height: 130px; padding-bottom: 7px; }
.chronicle { display: flex; flex-direction: column; }
.log-item { display: flex; gap: 8px; padding: 7px 1px; border-bottom: 1px solid rgba(231, 211, 170, .05); animation: log-in .4s ease; }
.log-item:last-child { border-bottom: 0; }
.log-turn { flex: 0 0 auto; width: 20px; padding-top: 1px; font-size: 7px; color: var(--gold-dim); letter-spacing: .4px; }
.log-copy { font-size: 9.5px; line-height: 1.45; color: #b8c4b8; }
.log-copy b { color: #e9dfc9; font-weight: 600; }
.log-item.war .log-copy b { color: #e99780; }
.log-item.good .log-copy b { color: #8bd8bd; }
.log-item.empty { color: var(--muted-2); font-size: 9px; display: block; padding: 14px 2px; line-height: 1.5; }

/* ---------- board ---------- */
.board-stage {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
}
.board-topline {
  width: min(100%, calc(100dvh - 186px));
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 2px;
  font-size: 8px;
  letter-spacing: 1.8px;
  color: var(--muted-2);
  text-transform: uppercase;
}
.board-topline > div { display: flex; align-items: center; gap: 7px; }
.live-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 8px rgba(230, 183, 94, .6); animation: breathe 2.4s infinite; }
.board-coords { color: #8d9d8f; }
.board-coords span { color: var(--gold); }
.board-frame {
  width: min(100%, calc(100dvh - 186px));
  aspect-ratio: 1;
  flex: 0 1 auto;
  position: relative;
  padding: 11px;
  border-radius: 12px;
  background:
    linear-gradient(135deg, rgba(230, 183, 94, .5), rgba(72, 52, 24, .3) 16%, rgba(15, 28, 21, .9) 30%, rgba(31, 54, 41, .95) 64%, rgba(101, 77, 39, .45) 100%),
    #16291f;
  box-shadow:
    0 0 0 1px rgba(255, 232, 176, .19),
    0 22px 60px rgba(0, 0, 0, .46),
    0 4px 0 #09130e,
    inset 0 0 0 2px rgba(10, 22, 16, .8),
    inset 0 0 28px rgba(230, 183, 94, .08);
}
.board-frame::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid rgba(255, 236, 188, .2);
  border-radius: 7px;
  pointer-events: none;
  z-index: 3;
}
.board {
  position: relative;
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  grid-template-rows: repeat(10, 1fr);
  overflow: hidden;
  border-radius: 4px;
  background: #15383b;
  box-shadow: inset 0 0 34px rgba(0, 0, 0, .55);
  isolation: isolate;
}
.tile {
  position: relative;
  min-width: 0;
  min-height: 0;
  padding: 0;
  border: 0;
  overflow: hidden;
  cursor: pointer;
  background-color: #3e6546;
  -webkit-tap-highlight-color: transparent;
}
.tile::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .055), transparent 40%, rgba(0, 0, 0, .08)),
    radial-gradient(90% 80% at 20% 10%, rgba(255, 255, 255, .05), transparent 60%);
  transition: box-shadow .15s, background .15s;
}
.tile::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 11;
  pointer-events: none;
  box-shadow: inset 0 0 0 0 rgba(255, 235, 177, 0);
  transition: box-shadow .14s ease;
}
.tile:hover::after { box-shadow: inset 0 0 0 2px rgba(255, 235, 177, .54), inset 0 0 22px rgba(255, 235, 177, .1); }
.tile.selected::after { box-shadow: inset 0 0 0 3px #ffdf9b, inset 0 0 30px rgba(255, 215, 137, .23); }
.tile.reachable { cursor: pointer; }
.tile.reachable::after { box-shadow: inset 0 0 0 1px rgba(125, 224, 191, .55), inset 0 0 18px rgba(81, 195, 160, .12); }
.tile.attackable::after { box-shadow: inset 0 0 0 2px rgba(231, 108, 79, .85), inset 0 0 24px rgba(231, 108, 79, .2); }
.tile.city-tile::before { background: linear-gradient(180deg, rgba(255, 255, 255, .09), transparent 50%, rgba(0, 0, 0, .1)); }
.tile-deco { position: absolute; inset: 0; z-index: 1; opacity: .9; pointer-events: none; }
.tile-deco svg { width: 100%; height: 100%; overflow: visible; }
.tile-deco .deco-soft { opacity: .5; }
.tile-tint { position: absolute; inset: 0; z-index: 0; pointer-events: none; }
.t-ocean { background: #153d48; }
.t-ocean .tile-tint { background: radial-gradient(80% 80% at 70% 20%, rgba(45, 126, 139, .25), transparent 60%); }
.t-coast { background: #28616a; }
.t-coast .tile-tint { background: linear-gradient(180deg, rgba(239, 216, 162, .15), transparent 20%, rgba(0, 0, 0, .05)); }
.t-grass { background: #6f8d4e; }
.t-grass .tile-tint { background: radial-gradient(80% 65% at 30% 20%, rgba(200, 211, 122, .2), transparent 65%); }
.t-plains { background: #a49a51; }
.t-plains .tile-tint { background: radial-gradient(90% 70% at 70% 15%, rgba(231, 205, 113, .22), transparent 65%); }
.t-forest { background: #406b4a; }
.t-forest .tile-tint { background: radial-gradient(80% 70% at 50% 30%, rgba(41, 99, 65, .32), transparent 70%); }
.t-hills { background: #8b7a52; }
.t-hills .tile-tint { background: radial-gradient(90% 70% at 50% 80%, rgba(75, 62, 35, .25), transparent 70%); }
.t-mountain { background: #77736a; }
.t-mountain .tile-tint { background: linear-gradient(180deg, rgba(255, 255, 255, .12), rgba(38, 42, 38, .16)); }
.t-desert { background: #c3a668; }
.t-desert .tile-tint { background: radial-gradient(80% 60% at 30% 20%, rgba(255, 231, 162, .22), transparent 65%); }

.edge {
  position: absolute;
  z-index: 9;
  pointer-events: none;
  opacity: .95;
  background: var(--territory, transparent);
  box-shadow: 0 0 7px color-mix(in srgb, var(--territory) 55%, transparent);
}
.edge.t { top: 0; left: 0; right: 0; height: 2px; }
.edge.b { bottom: 0; left: 0; right: 0; height: 2px; }
.edge.l { top: 0; bottom: 0; left: 0; width: 2px; }
.edge.r { top: 0; bottom: 0; right: 0; width: 2px; }
.edge.on { opacity: 1; }

.tile-improvement, .tile-feature {
  position: absolute;
  z-index: 7;
  pointer-events: none;
}
.tile-improvement { right: 3px; bottom: 3px; width: 25%; height: 25%; color: #f5eacb; filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .5)); }
.tile-improvement svg { width: 100%; height: 100%; }
.tile-feature {
  left: 4px;
  bottom: 4px;
  width: 29%;
  height: 29%;
  color: #f4cf78;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .65));
  animation: feature-glow 2.5s infinite;
}
.tile-feature svg { width: 100%; height: 100%; }
.move-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 10;
  width: 18%;
  height: 18%;
  min-width: 5px;
  min-height: 5px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: rgba(219, 255, 241, .92);
  border: 1px solid rgba(29, 94, 73, .75);
  box-shadow: 0 0 10px rgba(127, 242, 203, .7);
  opacity: 0;
  pointer-events: none;
  transition: opacity .12s;
}
.tile.reachable .move-dot { opacity: .82; animation: dot-pulse 1.5s infinite; }
.tile.reachable:hover .move-dot { opacity: 1; transform: translate(-50%, -50%) scale(1.25); }
.tile.attackable .move-dot { background: #ff8a6d; border-color: #7d2f1d; box-shadow: 0 0 12px rgba(255, 103, 74, .8); opacity: 1; }
.tile.selected .move-dot { opacity: 0; }

.tokens { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
.unit-token, .city-token {
  position: absolute;
  width: 10%;
  height: 10%;
  left: 0;
  top: 0;
  transform: translate(calc(var(--x) * 100%), calc(var(--y) * 100%));
  transition: transform .36s cubic-bezier(.22, .9, .3, 1.15);
  pointer-events: none;
  will-change: transform;
}
.unit-token { display: grid; place-items: center; z-index: 25; }
.unit-token .unit-body {
  position: relative;
  width: 58%;
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #f8eed8;
  border: 1.5px solid rgba(255, 235, 183, .78);
  box-shadow: 0 3px 6px rgba(0, 0, 0, .45), inset 0 1px rgba(255, 255, 255, .35), 0 0 0 2px rgba(15, 33, 24, .55);
  transition: transform .18s, box-shadow .18s;
}
.unit-token .unit-body::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, .16);
}
.unit-token.player .unit-body { background: radial-gradient(circle at 34% 26%, #81e5c3, #2d9e7d 44%, #145c4a 82%); }
.unit-token.rival .unit-body { background: radial-gradient(circle at 34% 26%, #ef9a7f, #c15a42 44%, #702a20 82%); border-color: rgba(255, 210, 188, .7); }
.unit-token .unit-body svg { width: 55%; height: 55%; filter: drop-shadow(0 1px 1px rgba(0, 0, 0, .3)); }
.unit-token.selected .unit-body { transform: scale(1.13); box-shadow: 0 0 0 4px rgba(255, 222, 150, .27), 0 0 18px rgba(255, 210, 120, .5), 0 3px 7px rgba(0, 0, 0, .45); animation: token-bob 1.8s ease-in-out infinite; }
.unit-token.fortified .unit-body { box-shadow: 0 0 0 2px rgba(181, 222, 255, .5), 0 0 12px rgba(125, 192, 255, .35), 0 3px 7px rgba(0, 0, 0, .45); }
.unit-token.spawning .unit-body { animation: spawn-pop .46s cubic-bezier(.2, 1.6, .5, 1); }
.unit-token .unit-hp {
  position: absolute;
  left: 50%;
  bottom: 4%;
  width: 48%;
  height: 3px;
  transform: translateX(-50%);
  border-radius: 99px;
  overflow: hidden;
  background: rgba(5, 17, 10, .7);
  box-shadow: 0 1px 2px rgba(0, 0, 0, .5);
}
.unit-token .unit-hp i { display: block; height: 100%; width: 100%; border-radius: inherit; background: #9fe1c9; }
.unit-token.rival .unit-hp i { background: #f0a48d; }
.unit-token .unit-move {
  position: absolute;
  left: 50%;
  top: -1px;
  display: flex;
  gap: 2px;
  transform: translate(-50%, -100%);
  opacity: 0;
  transition: opacity .15s;
}
.unit-token.selected .unit-move { opacity: 1; }
.unit-token .unit-move i { width: 4px; height: 4px; border-radius: 50%; background: #faebb9; box-shadow: 0 0 5px rgba(250, 235, 185, .6); }
.unit-token .unit-move i.spent { background: rgba(255, 255, 255, .2); box-shadow: none; }
.unit-token .unit-strength {
  position: absolute;
  right: 5%;
  top: 6%;
  min-width: 12px;
  height: 12px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #11251a;
  border: 1px solid rgba(255, 235, 183, .5);
  color: #f5e5c0;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0;
}
.tile.flash-hit .unit-body, .tile.flash-hit .city-token { animation: hit-shake .38s ease; }
.city-token {
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 20;
}
.city-token .city-sprite {
  width: 105%;
  height: 70%;
  filter: drop-shadow(0 4px 4px rgba(0, 0, 0, .42));
  transition: transform .18s;
}
.city-token.player .city-sprite { color: #7bd4b4; }
.city-token.rival .city-sprite { color: #de866e; }
.city-token .city-plate {
  position: absolute;
  bottom: -2%;
  left: 50%;
  max-width: 120%;
  transform: translateX(-50%);
  padding: 2px 5px 2px 6px;
  border-radius: 3px;
  white-space: nowrap;
  background: rgba(10, 24, 16, .88);
  border: 1px solid rgba(255, 235, 183, .27);
  color: #f3e7cd;
  font-family: var(--serif);
  font-size: clamp(6px, .58vw, 9px);
  line-height: 1.2;
  letter-spacing: .3px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, .4);
}
.city-token.rival .city-plate { border-color: rgba(231, 143, 116, .32); }
.city-token .city-hp {
  position: absolute;
  bottom: 11%;
  left: 50%;
  width: 48%;
  height: 3px;
  transform: translateX(-50%);
  border-radius: 99px;
  background: rgba(4, 14, 8, .65);
  overflow: hidden;
}
.city-token .city-hp i { display: block; height: 100%; width: 100%; background: #e7c46e; }
.city-token.rival .city-hp i { background: #df8068; }
.city-token.selected .city-sprite { transform: scale(1.08); }
.city-token .city-star {
  position: absolute;
  right: 6%;
  top: 2%;
  width: 16%;
  color: #f5d68b;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .45));
}
.city-token .city-star svg { width: 100%; height: 100%; }
.city-token .city-star { display: none; }
.city-token.capital .city-star { display: block; }
.city-token.spawning .city-sprite { animation: spawn-pop .46s cubic-bezier(.2, 1.6, .5, 1); }

.frame-corner { position: absolute; width: 17px; height: 17px; z-index: 28; pointer-events: none; border-color: rgba(255, 228, 161, .55); }
.frame-corner.tl { top: 4px; left: 4px; border-left: 1px solid; border-top: 1px solid; border-radius: 3px 0 0 0; }
.frame-corner.tr { top: 4px; right: 4px; border-right: 1px solid; border-top: 1px solid; border-radius: 0 3px 0 0; }
.frame-corner.bl { bottom: 4px; left: 4px; border-left: 1px solid; border-bottom: 1px solid; border-radius: 0 0 0 3px; }
.frame-corner.br { bottom: 4px; right: 4px; border-right: 1px solid; border-bottom: 1px solid; border-radius: 0 0 3px 0; }
.compass { position: absolute; top: 15px; right: 15px; width: 40px; height: 40px; z-index: 26; color: rgba(255, 235, 183, .52); opacity: .85; pointer-events: none; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, .3)); }
.compass svg { width: 100%; height: 100%; }
.map-scale { position: absolute; left: 15px; bottom: 13px; z-index: 26; display: flex; align-items: center; gap: 6px; color: rgba(255, 235, 183, .36); pointer-events: none; }
.map-scale span { display: block; width: 28px; height: 3px; border-left: 1px solid currentColor; border-right: 1px solid currentColor; border-bottom: 1px solid currentColor; }
.map-scale small { font-size: 6px; letter-spacing: 1.7px; }
.board-hint {
  width: min(100%, calc(100dvh - 186px));
  min-height: 35px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 11px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: linear-gradient(90deg, rgba(22, 42, 32, .8), rgba(17, 32, 24, .5));
  color: var(--muted);
  font-size: 9.5px;
  letter-spacing: .15px;
  line-height: 1.35;
}
.hint-icon { width: 21px; height: 21px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%; color: var(--gold); background: rgba(230, 183, 94, .09); }
.hint-icon svg { width: 13px; height: 13px; }
.board-hint b { color: #eed9ad; font-weight: 600; }
.board-hint .key { display: inline-block; padding: 1px 4px; margin: 0 1px; border-radius: 3px; background: rgba(255, 255, 255, .08); border: 1px solid rgba(255, 255, 255, .1); font-size: 8px; color: #e9dcc0; }

/* ---------- context panel ---------- */
.ctx-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(145deg, rgba(27, 48, 37, .8), rgba(14, 27, 21, .9));
  box-shadow: inset 0 1px rgba(255, 255, 255, .04), 0 14px 36px rgba(0, 0, 0, .16);
  overflow: hidden;
  position: relative;
}
.ctx-card::before {
  content: "";
  position: absolute; inset: 5px;
  border: 1px solid rgba(231, 211, 170, .045);
  border-radius: calc(var(--radius) - 6px);
  pointer-events: none;
}
.ctx-head {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 15px 15px 12px;
  border-bottom: 1px solid var(--line);
  position: relative;
}
.ctx-head.rival-head { background: linear-gradient(90deg, rgba(215, 111, 81, .07), transparent); }
.ctx-sigil {
  width: 40px; height: 40px; flex: 0 0 auto;
  display: grid; place-items: center;
  border-radius: 11px;
  background: linear-gradient(145deg, rgba(81, 195, 160, .2), rgba(17, 63, 49, .25));
  border: 1px solid rgba(81, 195, 160, .25);
  color: #9ce3cc;
}
.ctx-sigil svg { width: 24px; height: 24px; }
.ctx-sigil.rival { background: linear-gradient(145deg, rgba(215, 111, 81, .2), rgba(86, 35, 27, .25)); border-color: rgba(215, 111, 81, .25); color: #efa58e; }
.ctx-sigil.unit { border-radius: 50%; }
.ctx-head-copy { flex: 1; min-width: 0; }
.ctx-eyebrow { font-size: 7.5px; letter-spacing: 1.7px; text-transform: uppercase; color: var(--gold); }
.ctx-head-copy h2 { margin: 2px 0 0; font-family: var(--serif); font-size: 21px; font-weight: 500; letter-spacing: .2px; color: #f4ead4; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ctx-head-copy p { margin: 2px 0 0; font-size: 8.5px; color: var(--muted-2); letter-spacing: .4px; }
.ctx-badge {
  align-self: flex-start;
  padding: 3px 6px;
  border: 1px solid rgba(81, 195, 160, .24);
  border-radius: 99px;
  color: var(--player);
  background: rgba(81, 195, 160, .07);
  font-size: 7px;
  letter-spacing: .9px;
  text-transform: uppercase;
  white-space: nowrap;
}
.ctx-badge.rival { border-color: rgba(215, 111, 81, .25); color: var(--rival); background: rgba(215, 111, 81, .08); }
.ctx-body { padding: 12px 15px 15px; }
.ctx-subhead {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  margin: 0 0 8px; font-size: 8px; letter-spacing: 1.4px; text-transform: uppercase; color: var(--muted-2);
}
.ctx-subhead b { color: #efe2c7; font-weight: 500; letter-spacing: .4px; text-transform: none; font-size: 9px; }
.hp-line { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; font-size: 8px; color: var(--muted); }
.hp-line .progress-track { flex: 1; height: 4px; }
.hp-line .progress-track i { background: linear-gradient(90deg, #8f6d2f, #e6c16c); }
.hp-line.rival .progress-track i { background: linear-gradient(90deg, #7c3427, #d76f51); }
.hp-line b { color: #e8dec8; font-weight: 500; font-variant-numeric: tabular-nums; }
.yield-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; margin-bottom: 12px; }
.yield-cell {
  min-width: 0;
  padding: 7px 3px 6px;
  border: 1px solid rgba(231, 211, 170, .07);
  border-radius: 7px;
  background: rgba(0, 0, 0, .13);
  text-align: center;
}
.yield-cell small { display: block; font-size: 6.5px; letter-spacing: .8px; text-transform: uppercase; color: var(--muted-2); }
.yield-cell strong { display: block; margin-top: 3px; font-family: var(--serif); font-size: 15px; font-weight: 500; color: #f2e7ce; line-height: 1; font-variant-numeric: tabular-nums; }
.yield-cell.food strong { color: #b7d081; } .yield-cell.prod strong { color: #e7be75; } .yield-cell.gold strong { color: #edd084; } .yield-cell.science strong { color: #89c4df; }
.yield-cell em { display: block; margin-top: 2px; font-style: normal; font-size: 6px; color: var(--muted-2); }
.growth-block { margin-bottom: 13px; }
.growth-top { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 5px; font-size: 8px; color: var(--muted); }
.growth-top b { color: #cfdcc8; font-weight: 500; font-size: 9px; }
.growth-top .good { color: #a8d192; }
.growth-top .bad { color: var(--danger); }
.progress-track.growth i { background: linear-gradient(90deg, #567c2f, #a7cd6c); }
.production-box {
  border: 1px solid rgba(230, 183, 94, .17);
  border-radius: 9px;
  padding: 9px 10px;
  background: linear-gradient(145deg, rgba(230, 183, 94, .055), rgba(0, 0, 0, .08));
  margin-bottom: 12px;
}
.production-box.done { border-color: rgba(81, 195, 160, .22); }
.production-top { display: flex; align-items: center; gap: 8px; }
.production-icon { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 7px; color: var(--gold); background: rgba(230, 183, 94, .1); border: 1px solid rgba(230, 183, 94, .14); }
.production-icon svg { width: 16px; height: 16px; }
.production-copy { flex: 1; min-width: 0; }
.production-copy small { display: block; font-size: 6.5px; letter-spacing: 1.2px; text-transform: uppercase; color: var(--muted-2); }
.production-copy strong { display: block; margin-top: 1px; font-family: var(--serif); font-size: 13px; font-weight: 500; }
.production-turns { font-size: 8px; color: var(--gold-bright); white-space: nowrap; }
.production-box .progress-track { margin-top: 7px; height: 4px; }
.production-box .progress-track i { background: linear-gradient(90deg, #9b6f2b, #f0c56d); }
.prod-detail { display: flex; justify-content: space-between; margin-top: 5px; color: var(--muted-2); font-size: 7px; }
.build-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.build-card {
  position: relative;
  min-width: 0;
  min-height: 47px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 6px;
  text-align: left;
  border: 1px solid rgba(231, 211, 170, .105);
  border-radius: 7px;
  background: rgba(255, 255, 255, .018);
  cursor: pointer;
  transition: .16s ease;
}
.build-card:hover:not(:disabled) { border-color: rgba(230, 183, 94, .35); background: rgba(230, 183, 94, .055); transform: translateY(-1px); }
.build-card:disabled { cursor: not-allowed; opacity: .42; }
.build-card.active { border-color: rgba(230, 183, 94, .5); background: linear-gradient(145deg, rgba(230, 183, 94, .13), rgba(230, 183, 94, .03)); box-shadow: inset 0 0 14px rgba(230, 183, 94, .04); }
.build-icon { width: 22px; height: 22px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 5px; background: rgba(0, 0, 0, .18); color: #d9c794; }
.build-icon svg { width: 14px; height: 14px; }
.build-info { min-width: 0; }
.build-info strong { display: block; font-size: 8.5px; font-weight: 600; color: #e8dfc9; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.build-info small { display: block; margin-top: 1px; font-size: 6.5px; color: var(--muted-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.build-cost { position: absolute; right: 5px; top: 4px; font-size: 6px; color: var(--gold-dim); }
.build-card .lock { position: absolute; right: 5px; bottom: 4px; font-size: 6px; color: var(--muted-2); }
.build-note { margin: 7px 1px 0; color: var(--muted-2); font-size: 7px; line-height: 1.4; }
.unit-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; margin-bottom: 12px; }
.unit-stat { padding: 7px 4px; border: 1px solid rgba(231, 211, 170, .08); border-radius: 7px; background: rgba(0, 0, 0, .13); text-align: center; }
.unit-stat small { display: block; font-size: 6.5px; letter-spacing: .8px; text-transform: uppercase; color: var(--muted-2); }
.unit-stat strong { display: block; margin-top: 3px; font-family: var(--serif); font-size: 16px; font-weight: 500; color: #f0e4cc; }
.unit-stat strong span { font-family: var(--sans); font-size: 8px; color: var(--muted-2); }
.pill-row { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 11px; }
.pill { padding: 3px 7px; border-radius: 99px; border: 1px solid rgba(231, 211, 170, .12); background: rgba(0, 0, 0, .12); color: var(--muted); font-size: 7px; letter-spacing: .2px; }
.pill.good { color: #a7ddc5; border-color: rgba(81, 195, 160, .21); background: rgba(81, 195, 160, .05); }
.pill.warn { color: #eab39d; border-color: rgba(215, 111, 81, .22); background: rgba(215, 111, 81, .06); }
.action-list { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.action-btn {
  min-height: 37px;
  display: flex; align-items: center; justify-content: center; gap: 6px;
  padding: 7px 8px;
  border: 1px solid rgba(231, 211, 170, .15);
  border-radius: 7px;
  background: rgba(255, 255, 255, .025);
  color: #e3d8bf;
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: .15px;
  cursor: pointer;
  transition: .16s;
}
.action-btn svg { width: 13px; height: 13px; }
.action-btn:hover:not(:disabled) { border-color: rgba(230, 183, 94, .4); background: rgba(230, 183, 94, .07); transform: translateY(-1px); }
.action-btn.primary { border-color: rgba(81, 195, 160, .35); background: linear-gradient(145deg, rgba(81, 195, 160, .16), rgba(81, 195, 160, .04)); color: #b7efdc; }
.action-btn.gold { border-color: rgba(230, 183, 94, .4); background: linear-gradient(145deg, rgba(230, 183, 94, .16), rgba(230, 183, 94, .04)); color: #f4d998; }
.action-btn.danger { border-color: rgba(215, 111, 81, .35); background: rgba(215, 111, 81, .08); color: #efb29f; }
.action-btn.wide { grid-column: 1 / -1; }
.action-btn:disabled { opacity: .36; cursor: not-allowed; }
.terrain-card {
  display: flex; align-items: center; gap: 9px;
  padding: 9px;
  border: 1px solid rgba(231, 211, 170, .09);
  border-radius: 8px;
  background: rgba(0, 0, 0, .12);
  margin-bottom: 10px;
}
.terrain-thumb { width: 36px; height: 36px; flex: 0 0 auto; border-radius: 6px; overflow: hidden; background: #3e6546; border: 1px solid rgba(255, 255, 255, .12); position: relative; }
.terrain-thumb .tile-deco { transform: scale(.98); }
.terrain-thumb .thumb-surface { position: absolute; inset: 0; }
.terrain-copy { flex: 1; min-width: 0; }
.terrain-copy strong { display: block; font-family: var(--serif); font-size: 12px; font-weight: 500; color: #eee3cb; }
.terrain-copy small { display: block; margin-top: 2px; font-size: 7.5px; color: var(--muted-2); }
.terrain-yields { display: flex; gap: 4px; flex-wrap: wrap; margin-top: 4px; }
.terrain-yields span { font-size: 6.5px; color: var(--muted); padding: 1px 4px; border-radius: 3px; background: rgba(0, 0, 0, .2); }
.terrain-yields span.food { color: #b7d081; } .terrain-yields span.prod { color: #e7be75; } .terrain-yields span.gold { color: #edd084; } .terrain-yields span.science { color: #89c4df; }
.ctx-hint { margin: 10px 1px 0; padding-top: 9px; border-top: 1px solid rgba(231, 211, 170, .07); color: var(--muted-2); font-size: 7.5px; line-height: 1.45; }
.ctx-hint b { color: var(--gold); font-weight: 500; }
.rival-summary { padding: 11px 0; color: var(--muted); font-size: 9px; line-height: 1.55; }
.rival-summary b { color: #e7d9bd; font-weight: 500; }
.identity-line { display: flex; align-items: center; gap: 6px; margin-bottom: 8px; }
.identity-line .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--player); box-shadow: 0 0 8px var(--player-glow); }
.identity-line.rival .dot { background: var(--rival); box-shadow: 0 0 8px var(--rival-glow); }
.identity-line span { font-size: 8px; color: var(--muted); }
.identity-line b { margin-left: auto; color: #e8dcc3; font-size: 9px; font-weight: 500; }
.ctx-note { margin-top: 8px; color: var(--muted-2); font-size: 7.5px; line-height: 1.45; }
.ctx-note strong { color: #dfc98f; font-weight: 500; }

/* ---------- toast / effects ---------- */
.toast-layer { position: fixed; z-index: 80; left: 50%; bottom: 24px; display: flex; flex-direction: column; align-items: center; gap: 6px; transform: translateX(-50%); pointer-events: none; }
.toast {
  display: flex; align-items: center; gap: 8px;
  min-height: 34px;
  padding: 7px 13px;
  border: 1px solid rgba(231, 211, 170, .22);
  border-radius: 7px;
  background: rgba(12, 27, 20, .94);
  box-shadow: 0 12px 34px rgba(0, 0, 0, .45), inset 0 1px rgba(255, 255, 255, .04);
  color: #e9dfc8;
  font-size: 10px;
  letter-spacing: .15px;
  animation: toast-in .28s ease;
  backdrop-filter: blur(8px);
}
.toast::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 8px rgba(230, 183, 94, .6); }
.toast.good::before { background: var(--player); box-shadow: 0 0 8px var(--player-glow); }
.toast.war::before { background: var(--rival); box-shadow: 0 0 8px var(--rival-glow); }
.toast.out { animation: toast-out .25s forwards; }
.phase-banner {
  position: fixed;
  z-index: 70;
  top: 104px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 15px;
  border-radius: 99px;
  border: 1px solid rgba(215, 111, 81, .32);
  background: rgba(39, 20, 17, .92);
  color: #f0b49f;
  font-size: 9px;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  box-shadow: 0 10px 30px rgba(0, 0, 0, .4);
  backdrop-filter: blur(10px);
  animation: phase-in .25s ease;
}
.phase-spinner { width: 11px; height: 11px; border-radius: 50%; border: 1.5px solid rgba(240, 180, 159, .25); border-top-color: #f0b49f; animation: spin .8s linear infinite; }

.tooltip {
  position: fixed;
  z-index: 90;
  min-width: 128px;
  max-width: 205px;
  padding: 8px 10px;
  border: 1px solid rgba(231, 211, 170, .2);
  border-radius: 7px;
  background: rgba(9, 22, 15, .95);
  box-shadow: 0 12px 32px rgba(0, 0, 0, .4);
  color: #e9dfc9;
  font-size: 8.5px;
  line-height: 1.4;
  pointer-events: none;
  backdrop-filter: blur(8px);
}
.tooltip .tt-title { display: flex; justify-content: space-between; gap: 10px; font-family: var(--serif); font-size: 11px; color: #f3e8d0; }
.tooltip .tt-title span { color: var(--muted-2); font-family: var(--sans); font-size: 7px; }
.tooltip .tt-yields { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 5px; }
.tooltip .tt-yields span { padding: 1px 4px; border-radius: 3px; background: rgba(255, 255, 255, .055); color: var(--muted); font-size: 7px; }
.tooltip .tt-yields .food { color: #b7d081; } .tooltip .tt-yields .prod { color: #e7be75; } .tooltip .tt-yields .gold { color: #edd084; } .tooltip .tt-yields .science { color: #89c4df; }
.tooltip .tt-owner { margin-top: 5px; font-size: 7px; color: var(--gold); }
.tooltip .tt-extra { margin-top: 4px; color: var(--muted-2); font-size: 7px; }

/* ---------- modal ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(4, 10, 7, .7);
  backdrop-filter: blur(7px);
  animation: fade-in .18s ease;
}
.modal-card {
  width: min(580px, 100%);
  max-height: min(680px, 90dvh);
  overflow-y: auto;
  border: 1px solid rgba(231, 211, 170, .22);
  border-radius: 15px;
  background:
    linear-gradient(145deg, rgba(29, 51, 39, .98), rgba(12, 25, 18, .99)),
    #11211a;
  box-shadow: 0 35px 100px rgba(0, 0, 0, .65), inset 0 1px rgba(255, 255, 255, .06);
  padding: 22px;
  animation: modal-in .24s cubic-bezier(.2, .9, .3, 1.05);
  scrollbar-width: thin;
}
.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 14px; }
.modal-eyebrow { font-size: 8px; letter-spacing: 2.2px; color: var(--gold); text-transform: uppercase; }
.modal-head h2 { margin: 4px 0 0; font-family: var(--serif); font-size: 27px; font-weight: 500; color: #f6ecd6; }
.modal-head p { margin: 5px 0 0; color: var(--muted); font-size: 10px; line-height: 1.5; }
.modal-close { flex: 0 0 auto; width: 31px; height: 31px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 7px; background: rgba(255, 255, 255, .025); color: var(--muted); cursor: pointer; }
.modal-close:hover { color: var(--parchment); border-color: var(--line-bright); }
.modal-close svg { width: 16px; height: 16px; }
.tech-list { display: flex; flex-direction: column; gap: 6px; }
.tech-row {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 12px;
  text-align: left;
  border: 1px solid rgba(231, 211, 170, .09);
  border-radius: 8px;
  background: rgba(255, 255, 255, .018);
  cursor: pointer;
  transition: .16s;
}
.tech-row:hover:not(:disabled) { border-color: rgba(118, 183, 216, .32); background: rgba(118, 183, 216, .05); }
.tech-row.current { border-color: rgba(118, 183, 216, .42); background: linear-gradient(90deg, rgba(118, 183, 216, .1), transparent); }
.tech-row.done { opacity: .55; cursor: default; }
.tech-row .tech-icon { width: 35px; height: 35px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 8px; color: var(--science); background: rgba(118, 183, 216, .09); border: 1px solid rgba(118, 183, 216, .14); }
.tech-row .tech-icon svg { width: 19px; height: 19px; }
.tech-copy { flex: 1; min-width: 0; }
.tech-copy strong { display: block; font-family: var(--serif); font-size: 13px; font-weight: 500; color: #eee4cd; }
.tech-copy small { display: block; margin-top: 2px; color: var(--muted); font-size: 8px; line-height: 1.35; }
.tech-copy em { display: block; margin-top: 3px; color: var(--gold); font-size: 7px; font-style: normal; }
.tech-cost { flex: 0 0 auto; text-align: right; font-size: 8px; color: var(--muted); }
.tech-cost b { display: block; font-family: var(--serif); font-size: 16px; color: #d9e9ee; font-weight: 500; }
.tech-cost span { display: block; margin-top: 2px; font-size: 7px; color: var(--muted-2); }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.help-step { padding: 10px 12px; border: 1px solid rgba(231, 211, 170, .08); border-radius: 8px; background: rgba(0, 0, 0, .12); }
.help-step b { display: flex; align-items: center; gap: 7px; font-size: 9px; color: #eee2c8; font-weight: 600; }
.help-step b i { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; background: rgba(230, 183, 94, .1); color: var(--gold); font-size: 8px; font-style: normal; }
.help-step p { margin: 6px 0 0; color: var(--muted); font-size: 8px; line-height: 1.5; }
.help-tips { margin-top: 10px; padding: 10px 12px; border-left: 2px solid rgba(230, 183, 94, .4); background: rgba(230, 183, 94, .04); color: var(--muted); font-size: 8.5px; line-height: 1.55; }
.help-tips b { color: var(--gold); font-weight: 500; }
.modal-foot { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }
.modal-btn { padding: 8px 14px; border: 1px solid var(--line); border-radius: 7px; background: rgba(255, 255, 255, .03); color: #e5dac2; font-size: 9px; cursor: pointer; }
.modal-btn.primary { border-color: rgba(230, 183, 94, .42); background: linear-gradient(180deg, #e7bd68, #c69240); color: #281a06; font-weight: 700; }

/* ---------- end screen ---------- */
.end-overlay {
  position: fixed;
  inset: 0;
  z-index: 110;
  display: grid;
  place-items: center;
  padding: 20px;
  overflow: hidden;
  background: radial-gradient(80% 80% at 50% 45%, rgba(29, 57, 40, .72), rgba(4, 10, 7, .94));
  backdrop-filter: blur(9px);
  animation: fade-in .5s ease;
}
.end-rays {
  position: absolute;
  width: 150vmax;
  height: 150vmax;
  background: repeating-conic-gradient(from 0deg, rgba(230, 183, 94, .08) 0deg 6deg, transparent 6deg 18deg);
  mask-image: radial-gradient(circle, #000 0%, transparent 65%);
  animation: slow-spin 80s linear infinite;
  pointer-events: none;
}
.end-card {
  position: relative;
  width: min(560px, 100%);
  max-height: 92dvh;
  overflow-y: auto;
  padding: 30px 30px 25px;
  border: 1px solid rgba(230, 183, 94, .32);
  border-radius: 18px;
  background:
    radial-gradient(80% 70% at 50% 0%, rgba(230, 183, 94, .08), transparent 60%),
    linear-gradient(145deg, rgba(28, 49, 37, .99), rgba(9, 20, 14, .99));
  box-shadow: 0 40px 120px rgba(0, 0, 0, .7), inset 0 1px rgba(255, 255, 255, .06);
  text-align: center;
  animation: modal-in .4s cubic-bezier(.2, .9, .3, 1.05);
}
.end-crown { width: 58px; height: 58px; margin: 0 auto 11px; display: grid; place-items: center; border-radius: 50%; color: var(--gold-bright); border: 1px solid rgba(230, 183, 94, .3); background: radial-gradient(circle, rgba(230, 183, 94, .13), rgba(0, 0, 0, .05)); box-shadow: 0 0 35px rgba(230, 183, 94, .1); }
.end-crown svg { width: 30px; height: 30px; }
.end-card .eyebrow { font-size: 8px; letter-spacing: 2.5px; color: var(--gold); text-transform: uppercase; }
.end-card h2 { margin: 8px 0 7px; font-family: var(--serif); font-size: clamp(30px, 5vw, 44px); font-weight: 500; line-height: 1.05; color: #f8eed8; }
.end-card .end-sub { margin: 0 auto 19px; max-width: 390px; color: var(--muted); font-size: 10px; line-height: 1.55; }
.end-score-duel { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 14px; }
.end-side { padding: 12px 10px; border: 1px solid rgba(231, 211, 170, .11); border-radius: 9px; background: rgba(0, 0, 0, .17); text-align: left; }
.end-side.winner { border-color: rgba(230, 183, 94, .35); background: linear-gradient(145deg, rgba(230, 183, 94, .1), rgba(0, 0, 0, .13)); }
.end-side .name { display: flex; justify-content: space-between; align-items: center; font-size: 8px; color: var(--muted); }
.end-side .name b { font-family: var(--serif); font-size: 12px; color: #ece1c9; font-weight: 500; }
.end-side .score { margin-top: 4px; font-family: var(--serif); font-size: 31px; line-height: 1; color: #f4e8cf; }
.end-side .score small { font-family: var(--sans); font-size: 7px; color: var(--muted-2); letter-spacing: .8px; }
.end-side .tag { display: inline-block; margin-top: 6px; padding: 2px 6px; border-radius: 99px; background: rgba(230, 183, 94, .1); color: var(--gold); font-size: 6px; letter-spacing: .8px; text-transform: uppercase; }
.end-breakdown { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; margin-bottom: 17px; }
.end-stat { padding: 8px 4px; border: 1px solid rgba(231, 211, 170, .07); border-radius: 7px; background: rgba(0, 0, 0, .1); }
.end-stat small { display: block; font-size: 6px; letter-spacing: .8px; color: var(--muted-2); text-transform: uppercase; }
.end-stat strong { display: block; margin-top: 3px; font-family: var(--serif); font-size: 16px; font-weight: 500; color: #e9ddc5; }
.end-btn { width: 100%; padding: 11px; border: 1px solid rgba(255, 223, 159, .55); border-radius: 8px; background: linear-gradient(180deg, #efc66f, #c89542); color: #2a1b07; font-size: 10px; font-weight: 800; letter-spacing: 1.5px; text-transform: uppercase; cursor: pointer; }
.end-btn:hover { filter: brightness(1.07); }

/* ---------- animations ---------- */
@keyframes breathe { 0%, 100% { opacity: .45; transform: scale(.85); } 50% { opacity: 1; transform: scale(1.1); } }
@keyframes dot-pulse { 0%, 100% { box-shadow: 0 0 8px rgba(127, 242, 203, .55); } 50% { box-shadow: 0 0 16px rgba(127, 242, 203, .95); } }
@keyframes token-bob { 0%, 100% { transform: scale(1.13) translateY(0); } 50% { transform: scale(1.13) translateY(-2px); } }
@keyframes spawn-pop { 0% { transform: scale(.3); opacity: 0; } 75% { transform: scale(1.15); opacity: 1; } 100% { transform: scale(1); } }
@keyframes feature-glow { 0%, 100% { filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .65)) drop-shadow(0 0 2px rgba(244, 207, 120, .1)); } 50% { filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .65)) drop-shadow(0 0 6px rgba(244, 207, 120, .45)); } }
@keyframes hit-shake { 0%, 100% { transform: translateX(0); filter: brightness(1); } 25% { transform: translateX(-3px); filter: brightness(1.7); } 50% { transform: translateX(3px); } 75% { transform: translateX(-2px); } }
@keyframes chip-pulse { 0% { transform: scale(1); } 35% { transform: scale(1.04); border-color: rgba(230, 183, 94, .45); } 100% { transform: scale(1); } }
@keyframes log-in { from { opacity: 0; transform: translateY(-3px); } to { opacity: 1; transform: translateY(0); } }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px) scale(.97); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes toast-out { to { opacity: 0; transform: translateY(-4px); } }
@keyframes phase-in { from { opacity: 0; transform: translate(-50%, -6px); } to { opacity: 1; transform: translate(-50%, 0); } }
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes modal-in { from { opacity: 0; transform: translateY(12px) scale(.985); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes slow-spin { to { transform: rotate(360deg); } }

/* ---------- responsive ---------- */
@media (max-width: 1240px) {
  .topbar { gap: 14px; padding-left: 16px; padding-right: 16px; }
  .brand { min-width: 190px; }
  .layout { grid-template-columns: 248px minmax(380px, 1fr) 298px; gap: 12px; padding: 13px 14px 14px; }
  .legacy-big { font-size: 39px; }
  .res-chip { padding-right: 9px; }
  .res-copy strong { font-size: 16px; }
  .board-topline, .board-frame, .board-hint { width: min(100%, calc(100dvh - 178px)); }
}
@media (max-width: 1060px) {
  body { overflow: auto; }
  .app { height: auto; min-height: 100dvh; overflow: visible; }
  .topbar { position: sticky; top: 0; flex-wrap: wrap; }
  .resource-rail { order: 4; width: 100%; margin: 0; justify-content: flex-start; overflow-x: auto; padding-bottom: 2px; }
  .resource-rail::-webkit-scrollbar { display: none; }
  .top-actions { margin-left: auto; }
  .layout { display: flex; flex-direction: column; padding: 13px 16px 22px; }
  .board-stage { order: 1; width: 100%; }
  .right-panel { order: 2; width: 100%; max-width: 680px; margin: 0 auto; overflow: visible; }
  .left-panel { order: 3; width: 100%; max-width: 680px; margin: 0 auto; display: grid; grid-template-columns: 1fr 1fr; align-items: start; overflow: visible; gap: 10px; }
  .chronicle-card { grid-column: 1 / -1; min-height: 0; }
  .board-topline, .board-frame, .board-hint { width: min(100%, 680px); }
  .right-panel .ctx-card { margin-top: 12px; }
  .phase-banner { top: 130px; }
}
@media (max-width: 700px) {
  .topbar { padding: 9px 12px 8px; gap: 8px; min-height: 0; }
  .brand { min-width: 0; flex: 1; gap: 9px; }
  .brand-crest { width: 34px; height: 34px; }
  .brand-crest svg { width: 20px; height: 20px; }
  .brand-copy h1 { font-size: 17px; }
  .brand-copy p { font-size: 7px; letter-spacing: 1.5px; }
  .res-chip { height: 37px; gap: 6px; padding: 0 8px 0 5px; border-radius: 8px; flex: 0 0 auto; }
  .res-icon { width: 24px; height: 24px; }
  .res-icon svg { width: 14px; height: 14px; }
  .res-copy small { font-size: 6px; letter-spacing: 1px; }
  .res-copy strong { font-size: 14px; margin-top: 2px; }
  .res-rate { font-size: 7px; margin-bottom: 5px; }
  .legacy-chip { min-width: 77px; }
  .turn-meter { min-width: 82px; height: 37px; padding: 6px 8px; flex: 0 0 auto; }
  .turn-copy strong { font-size: 16px; }
  .turn-copy span { font-size: 6px; }
  .top-actions { gap: 5px; }
  .icon-btn { width: 32px; height: 32px; }
  .icon-btn svg { width: 15px; height: 15px; }
  .btn-end { height: 38px; padding: 0 11px; font-size: 8px; letter-spacing: .9px; gap: 4px; }
  .btn-end svg { width: 12px; height: 12px; }
  .layout { padding: 9px 9px 18px; gap: 10px; }
  .board-topline { font-size: 6.5px; letter-spacing: 1.2px; }
  .board-frame { padding: 6px; border-radius: 8px; }
  .board-frame::before { inset: 3px; }
  .compass { width: 25px; height: 25px; top: 9px; right: 9px; }
  .map-scale { left: 8px; bottom: 7px; }
  .map-scale small { font-size: 5px; letter-spacing: 1px; }
  .map-scale span { width: 17px; }
  .board-hint { font-size: 8px; padding: 6px 8px; min-height: 32px; }
  .hint-icon { width: 18px; height: 18px; }
  .unit-token .unit-body { width: 65%; border-width: 1px; }
  .unit-token .unit-strength { min-width: 10px; height: 10px; font-size: 6px; }
  .city-token .city-plate { font-size: 5.5px; padding: 1px 3px; }
  .left-panel { display: flex; flex-direction: column; }
  .chronicle-card { min-height: 120px; }
  .ctx-card { border-radius: 12px; }
  .ctx-head { padding: 12px 12px 10px; }
  .ctx-head-copy h2 { font-size: 18px; }
  .ctx-body { padding: 10px 12px 13px; }
  .toast-layer { bottom: 12px; width: calc(100% - 20px); }
  .toast { font-size: 9px; }
  .phase-banner { top: 96px; font-size: 7px; letter-spacing: 1px; }
  .end-card { padding: 23px 17px 18px; }
  .end-breakdown { gap: 4px; }
}
@media (max-width: 400px) {
  .brand-copy p { display: none; }
  .brand-copy h1 { font-size: 15px; }
  .btn-end span { display: none; }
  .btn-end { width: 36px; padding: 0; justify-content: center; }
  .btn-end svg { width: 15px; height: 15px; }
  .resource-rail { gap: 5px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

