import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors=[]; page.on('pageerror',e=>errors.push(e.message)); page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
for (let t=0; t<21; t++) {
  const s0 = await page.evaluate(() => window.PocketEmpire.getState());
  if (s0.ended) break;
  if (s0.phase !== 'player') { await page.waitForTimeout(250); continue; }
  // improve if possible with any worker
  await page.evaluate(() => {
    const s = window.PocketEmpire.getState();
    for (const u of s.units.filter(u=>u.owner==='player' && u.type==='worker' && u.moves>0)) {
      const tile=s.map[u.y][u.x]; const imp = tile && !tile.improvement && tile.owner==='player' ? true : false;
      if (imp) window.PocketEmpire.selectUnit(u.id);
    }
  });
  const improveBtn = page.locator('[data-action="improve"]');
  if (await improveBtn.count()) { try { await improveBtn.first().click(); } catch {} }
  // fortify all fighters
  await page.evaluate(() => {
    const s = window.PocketEmpire.getState();
    for (const u of s.units.filter(u=>u.owner==='player' && ['warrior','spearman','scout'].includes(u.type) && u.hp>=4 && !u.fortified)) {
      window.PocketEmpire.selectUnit(u.id);
    }
  });
  const fortify = page.locator('[data-action="fortify"]');
  if (await fortify.count()) { try { await fortify.first().click(); } catch {} }
  // set production warrior (city selected to get context? direct)
  await page.evaluate(() => { try { window.PocketEmpire.setProduction('sunfall','warrior'); } catch {} });
  await page.evaluate(() => window.PocketEmpire.endTurn());
  await page.waitForFunction(() => window.PocketEmpire.getState().phase === 'player' || window.PocketEmpire.getState().ended, null, { timeout: 20000 });
  const s = await page.evaluate(() => window.PocketEmpire.getState());
  console.log(`T${s.turn} ${s.ended?'END:'+s.endReason:''} gold=${s.factions.player.gold} cityHP=${s.cities.find(c=>c.name==='Sunfall')?.hp} units=${s.units.filter(u=>u.owner==='player').map(u=>u.type).join(',')} aiUnits=${s.units.filter(u=>u.owner==='ai').length}`);
  if (s.ended) break;
}
const s = await page.evaluate(() => window.PocketEmpire.getState());
console.log('final', s.turn, s.ended, s.endReason, s.cities.map(c=>c.owner+':'+c.name+':'+c.hp), 'errors', errors);
await browser.close();
EOF
