import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
page.on('pageerror', e => errors.push('PAGE ' + e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/pocket-mobile.png', fullPage: true });
console.log('errors:', errors);
console.log('body size:', await page.evaluate(() => ({ w: document.body.scrollWidth, h: document.body.scrollHeight, vw: innerWidth, vh: innerHeight })));
await browser.close();

