279: function findPath(unit, targetX, targetY, maxCost = Infinity, blockedByUnits = true) {
280:   const start = tileKey(unit.x, unit.y);
281:   const dist = new Map([[start, 0]]);
282:   const prev = new Map();
283:   const open = [{ x: unit.x, y: unit.y, cost: 0 }];
284:   while (open.length) {
285:     open.sort((a, b) => a.cost - b.cost);
286:     const node = open.shift();
287:     if (node.cost > (dist.get(tileKey(node.x, node.y)) ?? Infinity)) continue;
288:     if (node.cost > maxCost) continue;
289:     if (node.x === targetX && node.y === targetY) break;
290:     for (const n of neighbors(node.x, node.y)) {
291:       const tile = tileAt(n.x, n.y);
292:       if (!tile || !TERRAIN[tile.t].passable) continue;
293:       const otherUnit = unitAt(n.x, n.y);
294:       if (blockedByUnits && otherUnit && !(otherUnit.id === unit.id)) continue;
295:       const city = cityAt(n.x, n.y);
296:       if (city && city.owner !== unit.owner) continue;
297:       const cost = node.cost + (TERRAIN[tile.t].move || 1);
298:       if (cost > maxCost) continue;
299:       const key = tileKey(n.x, n.y);
300:       if (cost < (dist.get(key) ?? Infinity)) {
301:         dist.set(key, cost);
302:         prev.set(key, { x: node.x, y: node.y });
303:         open.push({ x: n.x, y: n.y, cost });
304:       }
305:     }
306:   }
307:   const goal = tileKey(targetX, targetY);
308:   if (!dist.has(goal)) return null;
309:   if (dist.get(goal) > maxCost) return null;
310:   const path = [];
311:   let cursor = goal;
312:   while (cursor !== start) {
313:     const [x, y] = cursor.split(',').map(Number);
314:     path.unshift({ x, y });
315:     const p = prev.get(cursor);
316:     if (!p) return null;
317:     cursor = tileKey(p.x, p.y);
318:   }
319:   return { path, cost: dist.get(goal) };
320: }
