230: function addScience(factionId, amount) {
231:   if (amount <= 0) return;
232:   const faction = getFaction(factionId);
233:   let remaining = amount;
234:   let guard = 0;
235:   while (remaining > 0 && guard < 10) {
236:     guard += 1;
237:     let techId = currentResearch(faction);
238:     if (!techId) {
239:       const next = nextResearch(faction);
240:       if (!next) {
241:         faction.bankedScience = (faction.bankedScience || 0) + remaining;
242:         break;
243:       }
244:       faction.research = next;
245:       techId = next;
246:     }
247:     const tech = TECHS[techId];
248:     const progress = researchProgress(faction, techId);
249:     const needed = tech.cost - progress;
250:     if (remaining >= needed) {
251:       remaining -= needed;
252:       faction.techs.push(techId);
253:       faction.progress[techId] = 0;
254:       if (factionId === 'player') {
255:         toast(`<b>Discovery:</b> ${tech.name} · ${tech.effect}`, 'good');
256:         makeLog(`Your scholars mastered <b>${tech.name}</b>. ${tech.effect}.`, 'good');
257:         sfx('research');
258:         pulseChip(dom.scienceChip);
259:       }
260:       faction.research = nextResearch(faction);
261:     } else {
262:       faction.progress[techId] = progress + remaining;
263:       remaining = 0;
264:     }
265:   }
266: }
