268: function processFactionTurn(factionId) {
269:   const faction = getFaction(factionId);
270:   const cities = citiesOf(factionId);
271:   let incomeGold = 0;
272:   let incomeScience = 0;
273:   for (const city of cities) {
274:     const y = cityYields(city);
275:     incomeGold += y.gold;
276:     incomeScience += y.science;
277:     city.maxHp = cityMaxHp(city);
278: 
279:     if (y.surplus !== 0) {
280:       city.food = Math.max(0, city.food + y.surplus);
281:     }
282:     let threshold = growthThreshold(city);
283:     let grew = false;
284:     while (city.food >= threshold && city.pop < 7) {
285:       city.food -= threshold;
286:       city.pop += 1;
287:       grew = true;
288:       const claimed = claimBestTile(city);
289:       if (factionId === 'player') {
290:         toast(`<b>${city.name}</b> grew to population ${city.pop}${claimed ? ` · borders reached ${formatCoord(claimed.x, claimed.y)}` : ''}.`, 'good');
291:         makeLog(`<b>${city.name}</b> grew to population ${city.pop}${claimed ? ` and claimed ${formatCoord(claimed.x, claimed.y)}` : ''}.`, 'good');
292:       } else if (claimed) {
293:         makeLog(`<b>${city.name}</b> expanded toward ${formatCoord(claimed.x, claimed.y)}.`, 'war');
294:       }
295:       threshold = growthThreshold(city);
296:     }
297:     if (city.pop >= 7 && city.food >= threshold) city.food = threshold - 1;
298:     if (grew && factionId === 'player') sfx('build');
299: 
300:     if (city.hp < city.maxHp && city.damagedTurn < state.turn) {
301:       city.hp = Math.min(city.maxHp, city.hp + 2);
302:     }
303: 
304:     city.prod += y.prod;
305:     let guard = 0;
306:     while (city.prod >= productionCost(city.prodItem) && guard < 3) {
307:       guard += 1;
308:       const finished = completeProduction(city, factionId);
309:       if (!finished) break;
310:     }
311:   }
312:   faction.gold += incomeGold;
313:   addScience(factionId, incomeScience);
314:   if (factionId === 'player') {
315:     pulseChip(dom.goldChip);
316:     pulseChip(dom.scienceChip, 80);
317:   }
318: }
