320: function completeProduction(city, factionId) {
321:   const itemId = city.prodItem;
322:   const def = PRODUCTION_DEFS[itemId];
323:   if (!def) {
324:     city.prodItem = factionId === 'ai' ? aiChooseProduction(city) : 'warrior';
325:     return false;
326:   }
327:   if (factionId === 'ai' && !isBuilding(itemId) && unitsOf('ai').length >= 4) {
328:     city.prod = 0;
329:     city.prodItem = aiChooseProduction(city);
330:     return false;
331:   }
332:   const cost = productionCost(itemId);
333: 
334:   if (isBuilding(itemId)) {
335:     if (hasBuilding(city, itemId)) {
336:       city.prod = 0;
337:       city.prodItem = factionId === 'ai' ? aiChooseProduction(city) : 'warrior';
338:       return false;
339:     }
340:     city.buildings.push(itemId);
341:     if (def.legacy) getFaction(factionId).legacyBonus = (getFaction(factionId).legacyBonus || 0) + def.legacy;
342:     if (itemId === 'walls') {
343:       city.maxHp = cityMaxHp(city);
344:       city.hp = Math.min(city.maxHp, city.hp + 10);
345:     }
346:     city.prod = Math.max(0, city.prod - cost);
347:     if (factionId === 'player') {
348:       toast(`<b>${city.name}</b> completed the <b>${def.name}</b>. ${def.effect}.`, 'good');
349:       makeLog(`<b>${def.name}</b> was completed in ${city.name}.`, 'good');
350:       sfx('build');
351:     } else {
352:       makeLog(`Cinderhold completed the <b>${def.name}</b>.`, 'war');
353:     }
354:     city.prodItem = factionId === 'ai' ? aiChooseProduction(city) : 'warrior';
355:     return true;
356:   }
357: 
358:   const tile = availableSpawnTile(city);
359:   if (!tile) {
360:     if (factionId === 'player') {
361:       toast(`<b>${city.name}</b> needs room for its ${def.name}.`, 'war');
362:       makeLog(`${city.name} trained a <b>${def.name}</b>, but there was no room to muster it.`, 'war');
363:     }
364:     return false;
365:   }
366:   createUnit({ type: itemId, owner: factionId, x: tile.x, y: tile.y, moves: 0 });
367:   city.prod = Math.max(0, city.prod - cost);
368:   if (factionId === 'player') {
369:     toast(`<b>${city.name}</b> mustered a <b>${def.name}</b>.`, 'good');
370:     makeLog(`${city.name} mustered a <b>${def.name}</b> at ${formatCoord(tile.x, tile.y)}.`, 'good');
371:     sfx('build');
372:   } else {
373:     makeLog(`Cinderhold mustered a <b>${def.name}</b>.`, 'war');
374:   }
375:   city.prodItem = factionId === 'ai' ? aiChooseProduction(city) : 'warrior';
376:   return true;
