505: function resolveUnitAttack(attacker, defender) {
506:   const tile = tileAt(defender.x, defender.y);
507:   const atk = unitStrength(attacker);
508:   const def = unitStrength(defender) + terrainDefence(tile) + (cityAt(defender.x, defender.y)?.owner === defender.owner ? cityDefenceBonus(cityAt(defender.x, defender.y)) : 0);
509:   const damage = clamp(5 + Math.round((atk - def) / 2), 3, 9);
510:   const retaliation = defender.hp - damage > 0 ? clamp(2 + Math.round((def - atk) / 2), 0, 4) : 0;
511:   state.stats.battles += 1;
512:   sfx('attack');
513:   defender.hp -= damage;
514:   if (retaliation > 0) attacker.hp -= retaliation;
515:   attacker.moves = 0;
516:   attacker.acted = true;
517:   attacker.fortified = false;
518: 
519:   const attackerName = UNIT_TYPES[attacker.type].name;
520:   const defenderName = UNIT_TYPES[defender.type].name;
521:   const attackerSide = attacker.owner === 'player' ? 'Your' : 'Cinder';
522:   const defenderSide = defender.owner === 'player' ? 'your' : 'Cinder';
523: 
524:   if (defender.hp <= 0) {
525:     state.units = state.units.filter(unit => unit.id !== defender.id);
526:     if (attacker.owner === 'player') {
527:       state.stats.kills += 1;
528:       makeLog(`Your <b>${attackerName}</b> slew a Cinder <b>${defenderName}</b> at ${formatCoord(defender.x, defender.y)}.`, 'good');
529:       toast(`<b>${defenderName} slain.</b> Your warrior takes the ground.`, 'good');
530:       attacker.x = defender.x;
531:       attacker.y = defender.y;
532:       if (tile.feature) collectFeature(attacker, tile);
533:     } else {
534:       state.stats.losses += 1;
535:       makeLog(`A Cinder <b>${defenderName}</b> slew your <b>${attackerName}</b> at ${formatCoord(defender.x, defender.y)}.`, 'war');
536:       toast(`Your <b>${attackerName}</b> was slain.`, 'war');
537:     }
538:     flashTile(defender.x, defender.y, defender.id);
539:   } else {
540:     const summary = `${attackerSide} ${attackerName} struck a ${defenderSide} ${defenderName} at ${formatCoord(defender.x, defender.y)} for <b>${damage}</b> damage.`;
541:     makeLog(summary, attacker.owner === 'player' ? 'good' : 'war');
542:     flashTile(defender.x, defender.y, defender.id);
543:     if (attacker.hp <= 0) {
544:       state.units = state.units.filter(unit => unit.id !== attacker.id);
545:       state.stats.losses += attacker.owner === 'player' ? 1 : 0;
546:       state.stats.kills += attacker.owner === 'ai' ? 1 : 0;
547:       makeLog(`${attackerSide} <b>${attackerName}</b> fell in the exchange.`, attacker.owner === 'player' ? 'war' : 'good');
548:     }
549:   }
550: 
551:   if (!getUnit(state.selected?.id) && state.selected?.type === 'unit') {
552:     const capital = getCity(getFaction('player').capitalId) || citiesOf('player')[0];
553:     state.selected = capital ? { type: 'city', id: capital.id } : null;
554:   }
555:   renderAll();
556: }
