558: function resolveCityAttack(attacker, city) {
559:   const atk = unitStrength(attacker);
560:   const def = cityDefence(city) + cityDefenceBonus(city);
561:   const damage = clamp(4 + Math.round((atk - def) / 2), 2, 9);
562:   city.hp -= damage;
563:   city.damagedTurn = state.turn;
564:   attacker.hp -= 1;
565:   attacker.moves = 0;
566:   attacker.acted = true;
567:   attacker.fortified = false;
568:   state.stats.battles += 1;
569:   sfx('attack');
570:   flashTile(city.x, city.y, city.id);
571: 
572:   if (attacker.owner === 'player') {
573:     makeLog(`Your <b>${UNIT_TYPES[attacker.type].name}</b> struck <b>${city.name}</b> for ${damage} damage.`, 'good');
574:   } else {
575:     makeLog(`Cinder forces struck <b>${city.name}</b> for ${damage} damage.`, 'war');
576:     toast(`<b>${city.name}</b> is under attack.`, 'war');
577:   }
578: 
579:   if (city.hp <= 0) {
580:     captureCity(city, attacker.owner, attacker);
581:   } else {
582:     if (attacker.hp <= 0) {
583:       state.units = state.units.filter(unit => unit.id !== attacker.id);
584:       makeLog(`Your <b>${UNIT_TYPES[attacker.type].name}</b> fell beneath the walls of ${city.name}.`, 'war');
585:       state.stats.losses += attacker.owner === 'player' ? 1 : 0;
