195: function syncTokens() {
196:   const wanted = new Set();
197:   const stackByTile = new Map();
198:   for (const unit of state.units) {
199:     const key = tileKey(unit.x, unit.y);
200:     const list = stackByTile.get(key) || [];
201:     list.push(unit.id);
202:     stackByTile.set(key, list);
203:   }
204: 
205:   for (const city of state.cities) {
206:     const id = `city-${city.id}`;
207:     wanted.add(id);
208:     let el = tokenEls.get(id);
209:     if (!el) {
210:       el = document.createElement('div');
211:       el.className = 'city-token';
212:       el.innerHTML = `
213:         <svg class="city-sprite" aria-hidden="true"><use href="#i-city"></use></svg>
214:         <span class="city-star">${icon('crown')}</span>
215:         <span class="city-plate"></span>
216:         <span class="city-hp"><i></i></span>
217:       `;
218:       dom.tokenLayer.appendChild(el);
219:       tokenEls.set(id, el);
220:     }
221:     const selected = state.selected?.type === 'city' && state.selected.id === city.id;
222:     const cityHit = ui.flashing.has(city.id);
223:     const garrison = unitAt(city.x, city.y);
224:     el.className = `city-token ${city.owner}${selected ? ' selected' : ''}${city.capital ? ' capital' : ''}${cityHit ? ' hit' : ''}${garrison ? ' garrisoned' : ''}`;
225:     el.style.setProperty('--x', city.x);
226:     el.style.setProperty('--y', city.y);
227:     el.style.zIndex = String(16 + city.y * 2);
228:     el.querySelector('.city-plate').textContent = city.name;
229:     el.querySelector('.city-hp i').style.width = pct(city.hp, city.maxHp);
230:     el.setAttribute('title', `${city.name} · ${city.owner === 'player' ? 'Your city' : 'Cinder Court'} · Pop ${city.pop}`);
231:   }
232: 
233:   for (const unit of state.units) {
234:     const id = `unit-${unit.id}`;
235:     wanted.add(id);
236:     let el = tokenEls.get(id);
237:     if (!el) {
238:       el = document.createElement('div');
239:       el.className = 'unit-token';
240:       el.innerHTML = `
241:         <span class="unit-move"></span>
242:         <span class="unit-body">${icon(UNIT_TYPES[unit.type].icon)}</span>
243:         <span class="unit-strength"></span>
244:         <span class="unit-hp"><i></i></span>
245:       `;
246:       dom.tokenLayer.appendChild(el);
247:       tokenEls.set(id, el);
248:     }
249:     const selected = state.selected?.type === 'unit' && state.selected.id === unit.id;
250:     const spawning = ui.spawning.has(unit.id);
251:     const flashing = ui.flashing.has(unit.id);
252:     const cityHere = cityAt(unit.x, unit.y);
253:     const stack = stackByTile.get(tileKey(unit.x, unit.y)) || [];
254:     const stackIndex = Math.max(0, stack.indexOf(unit.id));
255:     const stacked = Boolean(cityHere) || stack.length > 1;
256:     let ox = cityHere ? 34 : 0;
257:     let oy = cityHere ? 24 : 0;
258:     if (stackIndex > 0) {
259:       ox += (stackIndex % 2 === 1 ? 20 : -8);
260:       oy += stackIndex * 13;
261:     }
262:     el.className = `unit-token ${unit.owner}${selected ? ' selected' : ''}${unit.fortified ? ' fortified' : ''}${spawning ? ' spawning' : ''}${flashing ? ' hit' : ''}${stacked ? ' stacked' : ''}`;
263:     el.style.setProperty('--x', unit.x);
264:     el.style.setProperty('--y', unit.y);
265:     el.style.setProperty('--ox', `${ox}%`);
266:     el.style.setProperty('--oy', `${oy}%`);
267:     el.style.zIndex = String(24 + unit.y * 2 + (selected ? 10 : 0));
268:     el.querySelector('.unit-body').innerHTML = icon(UNIT_TYPES[unit.type].icon);
269:     el.querySelector('.unit-hp i').style.width = pct(unit.hp, unit.maxHp);
270:     el.querySelector('.unit-strength').textContent = String(unitStrength(unit));
271:     const pips = [];
272:     for (let i = 0; i < unit.maxMoves; i += 1) {
273:       pips.push(`<i class="${i >= unit.moves ? 'spent' : ''}"></i>`);
274:     }
275:     el.querySelector('.unit-move').innerHTML = pips.join('');
276:     el.setAttribute('title', `${UNIT_TYPES[unit.type].name} · ${unit.hp}/${unit.maxHp} HP`);
277:     if (spawning && !el.dataset.spawnTimer) {
278:       el.dataset.spawnTimer = '1';
279:       window.setTimeout(() => {
280:         ui.spawning.delete(unit.id);
281:         el.classList.remove('spawning');
282:         delete el.dataset.spawnTimer;
283:       }, 620);
284:     }
285:   }
286: 
287:   for (const [id, el] of tokenEls) {
288:     if (!wanted.has(id)) {
289:       el.remove();
290:       tokenEls.delete(id);
291:     }
292:   }
293: }
