463: function advisorHTML() {
464:   const player = calcLegacy('player');
465:   const rival = calcLegacy('ai');
466:   const faction = getFaction('player');
467:   const delta = player.total - rival.total;
468:   const notes = [];
469:   const fighters = unitsOf('player').filter(canFight);
470:   const enemyFighters = unitsOf('ai').filter(canFight);
471:   const cost = claimCost();
472:   const techId = currentResearch(faction);
473:   const tech = techId ? TECHS[techId] : null;
474:   const turns = tech ? researchTurns(faction) : null;
475: 
476:   if (delta < 0) {
477:     notes.push(`<b>Cinderhold leads by ${Math.abs(delta)} legacy.</b> Population and claimed land are the fastest ways to close the gap.`);
478:   } else if (delta === 0) {
479:     notes.push('<b>The realms are level.</b> One discovery or a few claimed tiles can break the tie.');
480:   } else {
481:     notes.push(`<b>You lead by ${delta} legacy.</b> Hold the frontier and keep the Cinder banners at arm's length.`);
482:   }
483: 
484:   if (state.turn >= 4 && fighters.length < 2) {
485:     notes.push(`Only <b>${fighters.length} fighter${fighters.length === 1 ? '' : 's'}</b> guard the Reach. Raise a warrior before the Cinder Court marches.`);
486:   } else if (enemyFighters.length > fighters.length && state.turn >= 6) {
487:     notes.push(`The Cinder Court fields <b>${enemyFighters.length} fighters</b> to your ${fighters.length}. Fortify forest and hill tiles for extra defence.`);
488:   } else if (state.turn >= 6 && enemyFighters.length) {
489:     notes.push(`Cinder banners are on the move. Keep a fighter beside <b>Sunfall</b> and use hills or forests as shields.`);
490:   }
491: 
492:   if (faction.gold >= cost) {
493:     notes.push(`You hold <b>${faction.gold} gold</b>; a frontier tile costs ${cost}. Claiming land adds legacy and feeds a nearby city.`);
494:   } else if (tech) {
495:     notes.push(`Scholars need <b>${turns || '—'} ${turns === 1 ? 'turn' : 'turns'}</b> to master ${tech.name}. Libraries and mountain tiles add science.`);
496:   }
497: 
498:   if (notes.length < 3) {
499:     const worker = unitsOf('player').find(unit => unit.type === 'worker');
500:     if (worker) {
501:       const tile = tileAt(worker.x, worker.y);
502:       const improvement = tile ? improvementForTile(tile) : null;
503:       if (tile?.owner === 'player' && improvement && canImproveTile(tile, 'player')) {
504:         notes.push(`Your worker can raise a <b>${IMPROVEMENTS[improvement].name}</b> at ${formatCoord(tile.x, tile.y)} for a lasting yield bonus.`);
