510:     if (ready) notes.push(`<b>${ready} unit${ready === 1 ? '' : 's'}</b> still ${ready === 1 ? 'has' : 'have'} orders this turn. Unused moves are lost when the turn ends.`);
511:   }
512:   if (!notes.length) notes.push('The map is quiet. Grow a city, deepen your research, and prepare for the final years.');
513: 
514:   return `<div class="ctx-card notes-card">
515:     <div class="notes-head">
516:       <span class="notes-icon">${icon('compass')}</span>
517:       <div class="notes-head-copy"><small>Field notes</small><strong>Advisor's counsel</strong></div>
518:     </div>
