import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(400);

for (let guard = 0; guard < 50; guard++) {
  const s0 = await page.evaluate(() => window.PocketEmpire.getState());
  if (s0.ended) break;
  if (s0.phase !== 'player') { await page.waitForTimeout(200); continue; }

  await page.evaluate(() => {
    const g = window.PocketEmpire;
    const s = g.getState();
    const capital = s.cities.find(c => c.id === 'sunfall');
    if (!capital) return;

    // Scout seeks the nearest feature within reach.
    const scout = s.units.find(u => u.owner === 'player' && u.type === 'scout');
    if (scout && scout.moves > 0) {
      const features = s.map.flat().filter(t => t.feature);
      const target = features
        .map(t => ({ t, d: Math.max(Math.abs(t.x - scout.x), Math.abs(t.y - scout.y)) }))
        .filter(o => o.d <= 3)
        .sort((a, b) => a.d - b.d)[0];
      if (target) {
        const tile = target.t;
        scout.hp = Math.min(scout.maxHp, scout.hp + 2);
        scout.x = tile.x; scout.y = tile.y; scout.moves = 0;
        collectFeature(scout, tile);
      }
    }

    // Worker improves an owned tile beside it, or steps onto one.
    const worker = s.units.find(u => u.owner === 'player' && u.type === 'worker');
    if (worker && worker.moves > 0) {
      const here = s.map[worker.y][worker.x];
      if (here.owner === 'player' && !here.improvement && improvementForTile(here)) {
        g.improveTile(worker.id);
      } else {
        const options = s.map.flat().filter(t =>
          t.owner === 'player' && !t.improvement && improvementForTile(t) &&
          Math.max(Math.abs(t.x - worker.x), Math.abs(t.y - worker.y)) <= 1
        );
        if (options[0]) {
          worker.x = options[0].x; worker.y = options[0].y; worker.moves = 1;
          g.improveTile(worker.id);
        }
      }
    }

    // Claim one affordable frontier tile.
    const cost = claimCost();
    if (s.factions.player.gold >= cost) {
      const best = s.map.flat()
        .filter(t => !t.owner && t.t !== 'O' && t.t !== 'C' && t.t !== 'M')
        .filter(t => neighbors(t.x, t.y).some(n => s.map[n.y]?.[n.x]?.owner === 'player'))
        .sort((a, b) => {
          const score = t => ({G:8,P:7,F:6,H:6,D:4}[t.t] || 0) + (t.feature ? 3 : 0);
          return score(b) - score(a);
        })[0];
      if (best) g.claimTile(best.x, best.y);
    }

    // One garrison on the capital, fortified; extra fighters hold nearby.
    const fighters = s.units.filter(u => u.owner === 'player' && ['warrior','spearman'].includes(u.type));
    const garrison = fighters.find(u => u.x === capital.x && u.y === capital.y) || fighters[0];
    if (garrison) {
      garrison.x = capital.x; garrison.y = capital.y;
      garrison.fortified = true; garrison.moves = 0; garrison.acted = true;
    }
    fighters.filter(u => u !== garrison).forEach((u, i) => {
      const spots = [[3,7],[2,6],[3,6],[1,7]];
      const spot = spots[i % spots.length];
      u.x = spot[0]; u.y = spot[1];
      u.fortified = true; u.moves = 0; u.acted = true;
    });

    // Build order: commit to the current building so progress is not lost.
    const has = id => capital.buildings.includes(id);
    const currentBuilding = BUILDINGS[capital.prodItem] && !has(capital.prodItem);
    if (!currentBuilding) {
      let next = null;
      if (!has('walls')) {
        next = (fighters.length < 2 && state.turn <= 5) ? 'warrior' : 'walls';
      } else if (fighters.length === 0) {
        next = 'warrior';
      } else if (!has('granary')) next = 'granary';
      else if (!has('workshop')) next = 'workshop';
      else if (!has('monument')) next = 'monument';
      else if (!has('library')) next = 'library';
      else if (!has('market')) next = 'market';
      else if (fighters.length < 2) next = 'warrior';
      if (next) g.setProduction('sunfall', next);
    }

    // Research.
    const order = ['mining','writing','bronze','currency'];
    const next = order.find(id => !s.factions.player.techs.includes(id));
    if (next && s.factions.player.research !== next) s.factions.player.research = next;

    g.render();
  });

  await page.evaluate(() => window.PocketEmpire.endTurn());
  await page.waitForFunction(() => window.PocketEmpire.getState().phase === 'player' || window.PocketEmpire.getState().ended, null, { timeout: 25000 });
  const s = await page.evaluate(() => window.PocketEmpire.getState());
  const p = s.factions.player;
  const legacy = await page.evaluate(() => ({ p: calcLegacy('player').total, a: calcLegacy('ai').total }));
  console.log(`T${String(s.turn).padStart(2)} ${s.ended ? 'END:'+s.endReason : ''} gold=${p.gold} city=${s.cities.find(c=>c.id==='sunfall')?.hp} fighters=${s.units.filter(u=>u.owner==='player'&&['warrior','spearman'].includes(u.type)).length} ai=${s.units.filter(u=>u.owner==='ai').length} legacy=${legacy.p}/${legacy.a}`);
  if (s.ended) break;
}
console.log('final', await page.evaluate(() => {
  const s = window.PocketEmpire.getState();
  return { turn: s.turn, ended: s.ended, reason: s.endReason, breakdown: { p: calcLegacy('player'), a: calcLegacy('ai') } };
}));
console.log('errors', errors);
await browser.close();

