page.on('pageerror', e => errors.push('PAGE '+e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
for (let i=0;i<20;i++) {
  const st = await page.evaluate(() => window.PocketEmpire.getState());
  if (st.ended) { console.log('ENDED at', st.turn, st.endReason); break; }
  if (st.phase !== 'player') { await page.waitForTimeout(300); continue; }
  await page.evaluate(() => window.PocketEmpire.endTurn());
  await page.waitForFunction(() => window.PocketEmpire.getState().phase === 'player' || window.PocketEmpire.getState().ended, null, { timeout: 20000 });
  const s2 = await page.evaluate(() => window.PocketEmpire.getState());
  console.log(`turn ${s2.turn} phase ${s2.phase} ended ${s2.ended} gold ${s2.factions.player.gold} units ${s2.units.length} cities ${s2.cities.map(c=>c.owner+':'+c.name+':'+c.hp).join('|')}`);
  if (s2.ended) { console.log('reason', s2.endReason); break; }
}
const s = await page.evaluate(() => window.PocketEmpire.getState());
console.log('final', JSON.stringify({turn:s.turn,ended:s.ended,reason:s.endReason,players:s.cities.map(c=>({owner:c.owner,name:c.name,hp:c.hp,pop:c.pop})), logs:s.logs.slice(0,12).map(l=>l.html)}, null, 2));
console.log('scores', await page.evaluate(() => ({p: calcLegacy('player'), a: calcLegacy('ai')})));
console.log('errors', errors);
await page.screenshot({ path: '/tmp/pocket-end.png', fullPage: true });
await browser.close();

