import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: true, args: ['--no-sandbox'] });
const errors = [];
const results = [];

function check(name, ok, detail) {
  results.push({ name, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + detail : ''}`);
}

async function newPage(viewport = { width: 1440, height: 900 }) {
  const page = await browser.newPage({ viewport });
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGE ' + e.message));
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  return page;
}

const stateOf = page => page.evaluate(() => window.PocketEmpire.getState());

// ---------- A. claim tile + village reward + fortify label ----------
{
  const page = await newPage();
  const before = await stateOf(page);
  const goldBefore = before.factions.player.gold;

  await page.locator('.tile[data-x="2"][data-y="5"]').click();
  await page.waitForTimeout(250);
  const claimVisible = await page.locator('#contextPanel [data-action="claim"]').count();
  check('claim button visible on frontier tile', claimVisible === 1);
  await page.locator('#contextPanel [data-action="claim"]').click();
  await page.waitForTimeout(350);
  const afterClaim = await stateOf(page);
  check('tile 2,5 claimed through UI', afterClaim.map[5][2].owner === 'player', afterClaim.map[5][2].owner);
  check('claim cost deducted', afterClaim.factions.player.gold === goldBefore - 15, `${goldBefore} -> ${afterClaim.factions.player.gold}`);

  // village at 4,8, scout starts at 3,8
  await page.locator('.tile[data-x="3"][data-y="8"]').click();
  await page.waitForTimeout(200);
  await page.locator('.tile[data-x="4"][data-y="8"]').click();
  await page.waitForTimeout(900);
  const afterVillage = await stateOf(page);
  check('scout moved onto village tile', afterVillage.units.find(u => u.id === 'u3')?.x === 4 && afterVillage.units.find(u => u.id === 'u3')?.y === 8);
  check('village feature consumed', afterVillage.map[8][4].feature === null);
  check('village gold reward applied', afterVillage.factions.player.gold === afterClaim.factions.player.gold + 22, `${afterClaim.factions.player.gold} -> ${afterVillage.factions.player.gold}`);

  // fortify warrior and check label
  await page.locator('.tile[data-x="3"][data-y="7"]').click();
  await page.waitForTimeout(200);
  await page.locator('#contextPanel [data-action="fortify"]').click();
  await page.waitForTimeout(300);
  const fortPill = await page.locator('#contextPanel .pill.good').allTextContents();
  check('fortify pill advertises +4', fortPill.some(t => t.includes('+4 fortified')), JSON.stringify(fortPill));
  await page.screenshot({ path: '/tmp/ui-actions-claim.png' });
  await page.close();
}

// ---------- B. produce settler, move it out, found second city ----------
{
  const page = await newPage();
  // speed the existing production up so the settler can be completed by one UI turn.
  await page.evaluate(() => {
    const s = window.PocketEmpire.getState();
    s.cities.find(c => c.id === 'sunfall').prod = 27;
    window.PocketEmpire.render();
  });
  await page.locator('#contextPanel [data-action="produce"][data-item="settler"]').click();
  await page.waitForTimeout(200);
  await page.locator('#endTurnBtn').click();
  await page.waitForFunction(() => window.PocketEmpire.getState().phase === 'player', null, { timeout: 20000 });
  await page.waitForTimeout(300);
  let s = await stateOf(page);
  let settler = s.units.find(u => u.owner === 'player' && u.type === 'settler');
  check('settler completed from UI production', Boolean(settler), settler ? `at ${settler.x},${settler.y}` : 'missing');

  // Move toward 5,7 over turns, then found a city using the panel button.
  let guard = 0;
  while (settler && guard < 3 && !(settler.x === 5 && settler.y === 7)) {
    guard += 1;
    const tx = Math.min(5, settler.x + 2);
    const ty = 7;
    // refresh moves if spent
    s = await stateOf(page);
    settler = s.units.find(u => u.id === settler.id);
    if (!settler) break;
    if (settler.moves <= 0) {
      await page.locator('#endTurnBtn').click();
      await page.waitForFunction(() => window.PocketEmpire.getState().phase === 'player', null, { timeout: 20000 });
      await page.waitForTimeout(250);
      s = await stateOf(page);
      settler = s.units.find(u => u.id === settler.id);
      continue;
    }
    await page.locator(`.tile[data-x="${settler.x}"][data-y="${settler.y}"]`).click();
    await page.waitForTimeout(150);
    const target = `.tile[data-x="${tx}"][data-y="${ty}"]`;
    await page.locator(target).click();
    await page.waitForTimeout(900);
    s = await stateOf(page);
    settler = s.units.find(u => u.id === settler.id);
  }

  if (settler && settler.x === 5 && settler.y === 7) {
    await page.locator('.tile[data-x="5"][data-y="7"]').click();
    await page.waitForTimeout(200);
    const foundVisible = await page.locator('#contextPanel [data-action="found-city"]').count();
    check('found-city button visible on settler', foundVisible === 1);
    await page.locator('#contextPanel [data-action="found-city"]').click();
    await page.waitForTimeout(450);
    s = await stateOf(page);
    const city = s.cities.find(c => c.owner === 'player' && c.id !== 'sunfall');
    check('second city founded through UI', Boolean(city), city ? `${city.name} at ${city.x},${city.y}` : 'missing');
    if (city) {
      check('new city owns its own tile', s.map[city.y][city.x].owner === 'player' && s.map[city.y][city.x].cityId === city.id);
      check('new city claimed surrounding land', s.map.flat().filter(t => t.cityId === city.id).length >= 4, String(s.map.flat().filter(t => t.cityId === city.id).length));
    }
  } else {
    check('settler reached founding site', false, settler ? `${settler.x},${settler.y}` : 'missing');
  }
  await page.screenshot({ path: '/tmp/ui-actions-city.png' });
  await page.close();
}

// ---------- C. kill garrison then capture city (city-tile occupancy fix) ----------
{
  const page = await newPage();
  await page.evaluate(() => {
    const s = window.PocketEmpire.getState();
    // clear the eastern approaches
    s.units = s.units.filter(u => u.owner !== 'ai');
    const cinder = s.cities.find(c => c.id === 'cinderhold');
    cinder.hp = 2;
    // AI garrison on the city tile
    s.units.push({ id: 'test-garrison', type: 'warrior', owner: 'ai', x: cinder.x, y: cinder.y, hp: 10, maxHp: 10, moves: 0, maxMoves: 2, fortified: false, acted: false });
    // two attackers in reach
    const a = s.units.find(u => u.id === 'u1');
    a.x = cinder.x; a.y = cinder.y + 1; a.moves = 2; a.acted = false; a.hp = a.maxHp;
    s.units.push({ id: 'test-attacker2', type: 'warrior', owner: 'player', x: cinder.x - 1, y: cinder.y, hp: 10, maxHp: 10, moves: 2, maxMoves: 2, fortified: false, acted: false });
    window.PocketEmpire.render();
  });
  await page.waitForTimeout(300);

  // attack the garrison with the first warrior
  await page.locator('.tile[data-x="7"][data-y="3"]').click();
  await page.waitForTimeout(150);
  await page.locator('.tile[data-x="7"][data-y="2"]').click();
  await page.waitForTimeout(500);
  let s = await stateOf(page);
  const first = s.units.find(u => u.id === 'u1');
  check('garrison killed by first warrior', !s.units.some(u => u.id === 'test-garrison'));
  check('attacker does not occupy enemy city tile', first.x === 7 && first.y === 3, first ? `${first.x},${first.y}` : 'missing');
  check('city still Cinder after garrison dies', s.cities.find(c => c.id === 'cinderhold').owner === 'ai');
  check('turn not ended after garrison kill', !s.ended);

  // second warrior attacks the city and captures it
  await page.locator('.tile[data-x="6"][data-y="2"]').click();
  await page.waitForTimeout(150);
  await page.locator('.tile[data-x="7"][data-y="2"]').click();
  await page.waitForTimeout(800);
  s = await stateOf(page);
  check('second warrior captures city', s.cities.find(c => c.id === 'cinderhold').owner === 'player');
  check('conquest end state reached', s.ended && s.endReason === 'conquest', `${s.ended}/${s.endReason}`);
  check('end overlay visible', await page.evaluate(() => !document.getElementById('endOverlay').hidden));
  const title = await page.locator('#endCard h2').textContent();
  check('conquest title shown', title.includes('Cinder Court Falls'), title);
  await page.screenshot({ path: '/tmp/ui-actions-conquest.png' });
  await page.close();
}

// ---------- D. mobile controls + no horizontal overflow ----------
{
  const page = await newPage({ width: 390, height: 844 });
  await page.waitForTimeout(400);
  const dims = await page.evaluate(() => ({
    body: document.body.scrollWidth,
    app: document.querySelector('.app').scrollWidth,
    vw: innerWidth,
    label: document.getElementById('endTurnBtn').getAttribute('aria-label'),
    endRect: (() => { const r = document.getElementById('endTurnBtn').getBoundingClientRect(); return { left: r.left, right: r.right, width: r.width }; })()
  }));
  check('mobile no horizontal overflow', dims.body <= dims.vw && dims.app <= dims.vw, JSON.stringify(dims));
  check('mobile End Turn has accessible label', Boolean(dims.label), dims.label);
  check('mobile End Turn inside viewport', dims.endRect.right <= dims.vw, JSON.stringify(dims.endRect));
  await page.screenshot({ path: '/tmp/ui-actions-mobile.png', fullPage: true });
  await page.close();
}

console.log('\nERRORS:', errors.length ? errors : 'none');
const failed = results.filter(r => !r.ok);
console.log(`SUMMARY: ${results.length - failed.length}/${results.length} checks passed`);
await browser.close();
process.exit(failed.length || errors.length ? 1 : 0);

