import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/opt/google/chrome/chrome', headless: true, args: ['--no-sandbox'] });
for (const [name, width, height] of [['tablet-landscape', 1024, 768], ['tablet-portrait', 768, 1024], ['narrow-desktop', 1240, 800]]) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
  await page.waitForTimeout(700);
  await page.screenshot({ path: `/tmp/${name}.png`, fullPage: true });
  console.log(name, await page.evaluate(() => {
    const r = s => { const el = document.querySelector(s); const b = el.getBoundingClientRect(); return { x: +b.x.toFixed(0), w: +b.width.toFixed(0) }; };
    return { bodyW: document.body.scrollWidth, vw: innerWidth, board: r('.board-frame'), right: r('.right-panel'), left: r('.left-panel') };
  }), errors);
  await page.close();
}
await browser.close();
